import{_ as n,a0 as p,w as o,s as d,ao as r,I as i,x as e,a1 as t,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"awk 系列：如何让 awk 使用 Shell 变量 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何让 awk 使用 Shell 变量 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何让 awk 使用 Shell 变量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何让 awk 使用 Shell 变量 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 11 - How to Allow Awk to Use Shell Variables","title":"awk 系列：如何让 awk 使用 Shell 变量","tag":"awk","desc":""},"relativePath":"awk/Part 11 - How to Allow Awk to Use Shell Variables.md","filePath":"[post].md"}'),h={name:"awk/Part 11 - How to Allow Awk to Use Shell Variables.md"};function k(w,a,c,u,m,g){const s=p("Link");return o(),d("div",null,[a[13]||(a[13]=r(`<h1 id="awk-系列-如何让-awk-使用-shell-变量" tabindex="-1">awk 系列：如何让 awk 使用 Shell 变量 <a class="header-anchor" href="#awk-系列-如何让-awk-使用-shell-变量" aria-label="Permalink to “awk 系列：如何让 awk 使用 Shell 变量”">​</a></h1><p>当我们编写 shell 脚本时，我们通常会在脚本中包含其它小程序或命令，例如 awk 操作。对于 awk 而言，我们需要找一些将某些值从 shell 传递到 awk 操作中的方法。</p><p>我们可以通过在 awk 命令中使用 shell 变量达到目的，在 awk 系列的这一节中，我们将学习如何让 awk 使用 shell 变量，这些变量可能包含我们希望传递给 awk 命令的值。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/08/Use-Shell-Variables-in-Awk.png" alt=""></p><p>有两种可能的方法可以让 awk 使用 shell 变量：</p><h3 id="_1-使用-shell-引用" tabindex="-1">1. 使用 Shell 引用 <a class="header-anchor" href="#_1-使用-shell-引用" aria-label="Permalink to “1. 使用 Shell 引用”">​</a></h3><p>让我们用一个示例来演示如何在一条 awk 命令中使用 shell 引用来替代一个 shell 变量。在该示例中，我们希望在文件 /etc/passwd 中搜索一个用户名，过滤并输出用户的账户信息。</p><p>因此，我们可以编写一个 <code>test.sh</code> 脚本，内容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 读取用户名</span></span>
<span class="line"><span>read -p &quot;请输入用户名：&quot; username</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 在 /etc/passwd 中搜索用户名，然后在屏幕上输出详细信息</span></span>
<span class="line"><span>cat /etc/passwd | awk &quot;/$username/ &quot;&#39; { print $0 }&#39;</span></span></code></pre></div><p>然后，保存文件并退出。</p><p>上述 <code>test.sh</code> 脚本中 awk 命令的说明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/passwd | awk &quot;/$username/ &quot;&#39; { print $0 }&#39;</span></span></code></pre></div><p><code>&quot;/$username/ &quot;</code>：该 shell 引用用于在 awk 命令中替换 shell 变量 <code>username</code> 的值。<code>username</code> 的值就是要在文件 /etc/passwd 中搜索的模式。</p><p>注意，双引号位于 awk 脚本 <code>&#39;{ print $0 }&#39;</code> 之外。</p><p>接下来给脚本添加可执行权限并运行它，操作如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod  +x  test.sh</span></span>
<span class="line"><span>$ ./text.sh</span></span></code></pre></div><p>运行脚本后，它会提示你输入一个用户名，然后你输入一个合法的用户名并回车。你将会看到来自 /etc/passwd 文件中详细的用户账户信息，如下图所示：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/08/Shell-Script-to-Find-Username-in-Passwd-File.png" alt=""></p><p><em>在 Password 文件中查找用户名的 shell 脚本</em></p><h3 id="_2-使用-awk-进行变量赋值" tabindex="-1">2. 使用 awk 进行变量赋值 <a class="header-anchor" href="#_2-使用-awk-进行变量赋值" aria-label="Permalink to “2. 使用 awk 进行变量赋值”">​</a></h3><p>和上面介绍的方法相比，该方法更加单，并且更好。考虑上面的示例，我们可以运行一条简单的命令来完成同样的任务。 在该方法中，我们使用 <code>-v</code> 选项将一个 shell 变量的值赋给一个 awk 变量。</p><p>首先，创建一个 shell 变量 <code>username</code>，然后给它赋予一个我们希望在 /etc/passwd 文件中搜索的名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>username=&quot;aaronkilik&quot;</span></span></code></pre></div><p>然后输入下面的命令并回车：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /etc/passwd | awk -v name=&quot;$username&quot; &#39; $0 ~ name {print $0}&#39;</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/08/Find-Username-in-Password-File-Using-Awk.png" alt=""></p><p><em>使用 awk 在 Password 文件中查找用户名</em></p><p>上述命令的说明：</p><ul><li><code>-v</code>：awk 选项之一，用于声明一个变量</li><li><code>username</code>：是 shell 变量</li><li><code>name</code>：是 awk 变量</li></ul><p>让我们仔细瞧瞧 awk 脚本 <code>&#39; $0 ~ name {print $0}&#39;</code> 中的 <code>$0 ~ name</code>。还记得么，当我们在 awk 系列第四节中介绍 awk 比较运算符时，<code>value ~ pattern</code> 便是比较运算符之一，它是指：如果 <code>value</code> 匹配了 <code>pattern</code> 则返回 <code>true</code>。</p><p>cat 命令通过管道传给 awk 的 <code>output($0)</code> 与模式 <code>(aaronkilik)</code> 匹配，该模式即为我们在 /etc/passwd 中搜索的名称，最后，比较操作返回 <code>true</code>。接下来会在屏幕上输出包含用户账户信息的行。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>我们已经介绍了 awk 功能的一个重要部分，它能帮助我们在 awk 命令中使用 shell 变量。很多时候，你都会在 shell 脚本中编写小的 awk 程序或命令，因此，你需要清晰地理解如何在 awk 命令中使用 shell 变量。</p><p>在 awk 系列的下一个部分，我们将会深入学习 awk 功能的另外一个关键部分，即流程控制语句。所以请继续保持关注，并让我们坚持学习与分享。</p><hr>`,35)),i("p",null,[a[1]||(a[1]=e("via: ",-1)),t(s,{href:"http://www.tecmint.com/use-shell-script-variable-in-awk/"},{default:l(()=>[...a[0]||(a[0]=[e("http://www.tecmint.com/use-shell-script-variable-in-awk/",-1)])]),_:1})]),i("p",null,[a[5]||(a[5]=e("作者：",-1)),t(s,{href:"http://www.tecmint.com/author/aaronkili/"},{default:l(()=>[...a[2]||(a[2]=[e("Aaron Kili",-1)])]),_:1}),a[6]||(a[6]=e(" 译者：",-1)),t(s,{href:"https://github.com/chrisleegit"},{default:l(()=>[...a[3]||(a[3]=[e("ChrisLeeGit",-1)])]),_:1}),a[7]||(a[7]=e(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:l(()=>[...a[4]||(a[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[a[10]||(a[10]=e("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[8]||(a[8]=[e("LCTT",-1)])]),_:1}),a[11]||(a[11]=e(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:l(()=>[...a[9]||(a[9]=[e("Linux中国",-1)])]),_:1}),a[12]||(a[12]=e(" 荣誉推出",-1))])])}const x=n(h,[["render",k]]);export{C as __pageData,x as default};
